import {locationPhotos} from './site-assets';
import {useEffect,useRef,useState} from 'react';
import useEmblaCarousel from 'embla-carousel-react';
import {ArrowUpRight,ArrowLeft,ArrowRight,X,Pause,Play} from 'lucide-react';
const photos=[
 {file:'interior-clean',title:'Un loc pentru momentele tale',caption:'Lumină caldă, mese primitoare și timp petrecut împreună.'},
 {file:'interior-swings',title:'Detalii care te fac să rămâi',caption:'Flori, culoare și colțuri în care te simți acasă.'},
 {file:'interior-bar',title:'Atmosfera Casa Mia',caption:'De la prima cafea la un toast între prieteni.'},
 {file:'terrace',title:'Ne vedem pe terasă',caption:'O masă bună, în aer liber.'},
];
export default function LocationGallery(){
 const [selected,setSelected]=useState<number|null>(null),[active,setActive]=useState(0),[playing,setPlaying]=useState(true);
 const close=useRef<HTMLButtonElement>(null),trigger=useRef<HTMLElement|null>(null);
 const dragging=useRef(false),hovered=useRef(false),pauseUntil=useRef(0);
 const [viewport,api]=useEmblaCarousel({loop:true,align:'center',skipSnaps:false,duration:32,dragThreshold:6});
 const move=(index:number)=>{api?.scrollTo(index);pauseUntil.current=Date.now()+6500};
 const step=(direction:number)=>{direction>0?api?.scrollNext():api?.scrollPrev();pauseUntil.current=Date.now()+6500};
 const open=(index:number)=>{trigger.current=document.activeElement as HTMLElement;setSelected(index)};
 useEffect(()=>{
  if(!api)return;
  const update=()=>setActive(api.selectedScrollSnap());update();
  api.on('select',update).on('reInit',update);
  return()=>{api.off('select',update).off('reInit',update)};
 },[api]);
 useEffect(()=>{
  if(!api)return;
  const preference=matchMedia('(prefers-reduced-motion: reduce)');let visible=false;
  const observer=new IntersectionObserver(([entry])=>{visible=entry.isIntersecting},{threshold:.2});observer.observe(api.rootNode());
  const down=()=>{dragging.current=true;pauseUntil.current=Date.now()+6500};
  const up=()=>{dragging.current=false;pauseUntil.current=Date.now()+6500};
  api.on('pointerDown',down).on('pointerUp',up);
  const timer=setInterval(()=>{if(visible&&!document.hidden&&playing&&selected===null&&!preference.matches&&!dragging.current&&!hovered.current&&!api.rootNode().contains(document.activeElement)&&Date.now()>pauseUntil.current)api.scrollNext()},4200);
  return()=>{observer.disconnect();clearInterval(timer);api.off('pointerDown',down).off('pointerUp',up)};
 },[api,playing,selected!==null]);

 useEffect(()=>{
  if(selected===null)return;
  const old=document.body.style.overflow;document.body.style.overflow='hidden';close.current?.focus();
  const key=(e:KeyboardEvent)=>{
   if(e.key==='Escape')setSelected(null);
   if(e.key==='ArrowRight')setSelected(i=>((i??0)+1)%photos.length);
   if(e.key==='ArrowLeft')setSelected(i=>((i??0)+photos.length-1)%photos.length);
   if(e.key==='Tab'){const buttons=close.current?.parentElement?.querySelectorAll('button');if(!buttons?.length)return;const first=buttons[0],last=buttons[buttons.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}
  };
  document.addEventListener('keydown',key);return()=>{document.body.style.overflow=old;document.removeEventListener('keydown',key);trigger.current?.focus()};
 },[selected!==null]);
 return <section className="location-gallery location-carousel section" id="locatia" aria-label="Fotografii Casa Mia"><div className="wrap"><div className="section-head"><div><p className="eyebrow dark">INTRĂ ÎN ATMOSFERA CASA MIA</p><h2>Un loc în care<br/>să te simți <em>acasă.</em></h2></div><p className="location-intro">Mese în familie, întâlniri cu prietenii și ocazii speciale. Descoperă locul în care ne vedem.</p></div></div>
 <div ref={viewport} onPointerEnter={e=>{if(e.pointerType==='mouse')hovered.current=true}} onPointerLeave={()=>{hovered.current=false}} className="location-carousel-shell" role="region" aria-roledescription="carusel" aria-label="Imagini din restaurant și de pe terasă" onKeyDown={e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){e.preventDefault();step(e.key==='ArrowRight'?1:-1)}}}><div className="location-track">
 {photos.map((p,i)=><div className="location-slide" key={p.file} role="group" aria-roledescription="diapozitiv" aria-label={`${i+1} din 4`}><button className="location-photo" onClick={()=>open(i)} aria-label={'Vezi fotografia: '+p.title}><img src={locationPhotos[p.file]} alt={p.title} loading="lazy" width="1448" height="1086" draggable={false}/><span className="location-photo-copy"><span><small>CASA MIA BY OANA</small><strong>{p.title}</strong></span><ArrowUpRight size={22}/></span></button></div>)}
 </div></div>
 <div className="wrap location-carousel-footer"><div className="location-carousel-status"><span className="location-count">0{active+1}<i>/ 04</i></span><p>{photos[active].caption}</p></div><div className="location-carousel-controls"><button onClick={()=>step(-1)} aria-label="Fotografia anterioară în carusel"><ArrowLeft size={19}/></button><div className="location-dots" role="group" aria-label="Alege fotografia">{photos.map((p,i)=><button key={p.file} aria-label={`Fotografia ${i+1}: ${p.title}`} aria-pressed={active===i} className={active===i?'active':''} onClick={()=>move(i)}/>)}</div><button onClick={()=>step(1)} aria-label="Fotografia următoare în carusel"><ArrowRight size={19}/></button><button className="location-autoplay" onClick={()=>setPlaying(!playing)} aria-label={playing?'Oprește derularea automată':'Pornește derularea automată'}>{playing?<Pause size={15}/>:<Play size={15}/>}</button></div></div>
 {selected!==null&&<div className="location-lightbox" role="dialog" aria-modal="true" aria-label={photos[selected].title} onClick={e=>{if(e.target===e.currentTarget)setSelected(null)}}><div className="location-lightbox-inner"><button className="location-close" ref={close} onClick={()=>setSelected(null)} aria-label="Închide fotografiile"><X/></button><img src={locationPhotos[photos[selected].file]} alt={photos[selected].title}/><div className="location-lightbox-caption"><button onClick={()=>setSelected((selected+3)%4)} aria-label="Fotografia anterioară"><ArrowLeft/></button><div><h3>{photos[selected].title}</h3><p>{photos[selected].caption}</p></div><button onClick={()=>setSelected((selected+1)%4)} aria-label="Fotografia următoare"><ArrowRight/></button></div></div></div>}
 </section>
}

